/** Inactive real host: native intent/GameMode buckets, opaque ownership, contacts, legacy migration and process restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class TrapdoorFluidHostChecks {
    private static final BlockPos BASE=new BlockPos(3208,96,3208),DIAGONAL=BASE.south(4);private static int checks;private static Housing[] blocks=new Housing[2];private static BlockEntityType<NativeTrapdoorEntity>[] types=new BlockEntityType[2];
    private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("trapdoor-fluid-");}private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Trapdoor fluids: "+message);}
    private static final class Housing extends NativeTrapdoorBlock {final int index;Housing(int index){super(BlockBehaviour.Properties.of().strength(2.5F).noOcclusion().dynamicShape(),index==1);this.index=index;}protected BlockEntityType<?> entityType(){return types[index];}protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}}
    @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{for(int i=0;i<2;i++){blocks[i]=new Housing(i);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","trapdoor_fluid_fixture_"+i),blocks[i]);}});event.register(Registries.BLOCK_ENTITY_TYPE,h->{for(int i=0;i<2;i++){final int index=i;types[i]=BlockEntityType.Builder.of((pos,state)->new NativeTrapdoorEntity(types[index],pos,state),blocks[i]).build(null);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","trapdoor_fluid_fixture_"+i),types[i]);}});}}
    private static NativeTrapdoorEntity tile(ServerLevel level,BlockPos pos){return (NativeTrapdoorEntity)level.getBlockEntity(pos);}
    private static CompoundTag choices(){var tag=new CompoundTag();tag.putInt("TrapdoorTrigger",0);return tag;}
    private static CompoundTag fluids(int first,int second,int amount){var tag=new CompoundTag();var data=new CompoundTag();data.putString("EnvelopeOwner","private:trapdoor-envelope");for(int side=0;side<2;side++){int kind=side==0?first:second;if(kind==0)continue;var raw=new CompoundTag();raw.putString("FluidName",kind==1?"water":kind==2?"lava":"future:trapdoor-fluid");raw.putInt("Amount",amount);var extra=new CompoundTag();extra.putInt("FixtureKind",kind);raw.put("Tag",extra);if(kind==3)raw.putString("Owner","private:trapdoor-slot");data.put("Side"+side,raw);}tag.put(NativeFluidSlots.KEY,data);return tag;}
    private static NativeTrapdoorEntity put(ServerLevel level,BlockPos pos,int family,CompoundTag tag){level.getChunkAt(pos);level.setBlock(pos,blocks[family].defaultBlockState().setValue(NativeTrapdoorBlock.FACING,Direction.NORTH),18);var owner=tile(level,pos);owner.loadWithComponents(tag,level.registryAccess());owner.onLoad();owner.tickServer();owner.refreshFluidGeometry();return owner;}
    private static void clear(ServerLevel level){level.getChunkAt(BASE);for(int x=-3;x<=3;x++)for(int z=-3;z<=7;z++)for(int y=-2;y<=4;y++){var pos=BASE.offset(x,y,z);if(NativeFluidWorld.loaded(level,pos))level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);}}
    private static void aim(ServerPlayer actor,NativeTrapdoorEntity owner,boolean above){actor.setGameMode(GameType.SURVIVAL);actor.setShiftKeyDown(false);actor.getInventory().selected=0;actor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);actor.setPos(owner.getBlockPos().getX()+.5,owner.getBlockPos().getY()+(above?2:-1)-actor.getEyeHeight(),owner.getBlockPos().getZ()+.5);actor.setYRot(180);actor.setYHeadRot(180);actor.setXRot(above?90:-90);}
    private static void loadFluids(ServerLevel level,NativeTrapdoorEntity owner,CompoundTag data){var saved=owner.saveWithoutMetadata(level.registryAccess());saved.put(NativeFluidSlots.KEY,data.get(NativeFluidSlots.KEY).copy());owner.loadWithComponents(saved,level.registryAccess());NativeFluidWorld.changed(owner);}
    private static void write(ServerLevel level){clear(level);var owner=put(level,BASE,0,choices());need(owner.fluidVolumeSnapshot().cells().isEmpty(),"dry host avoids eager compact-volume preparation");var actor=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(level);actor.getInventory().clearContent();aim(actor,owner,true);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));need(TrapdoorUsePayload.apply(actor,new TrapdoorUsePayload(BASE,InteractionHand.MAIN_HAND))&&owner.containedFluids().get(1).getAmount()==1000&&actor.getMainHandItem().is(Items.BUCKET)&&!owner.open(),"actual nine-byte intent/GameMode fills upper side without toggling leaf");need(TrapdoorUsePayload.apply(actor,new TrapdoorUsePayload(BASE,InteractionHand.MAIN_HAND))&&owner.containedFluids().get(1).isEmpty()&&actor.getMainHandItem().is(Items.WATER_BUCKET),"actual intent drains owned upper bucket");
        aim(actor,owner,false);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));need(TrapdoorUsePayload.apply(actor,new TrapdoorUsePayload(BASE,InteractionHand.MAIN_HAND))&&owner.containedFluids().get(0).getAmount()==1000&&actor.getMainHandItem().is(Items.BUCKET),"actual bottom-face intent owns lower slot");owner.requestOpen(true);NativeFluidWorld.changed(owner);need(owner.effectiveFluidSnapshot().side(1).fluid().is(Fluids.WATER)&&!owner.containedFluids().occupied(1),"opening borrows opposite water without moving owned storage");for(Direction direction:Direction.values())need(level.getFluidState(BASE.relative(direction)).isEmpty(),"Trapdoors never publish vanilla gush outlets");
        double best=0;Vec3 point=null;for(var cell:owner.fluidVolumeSnapshot().cells()){var box=cell.box();double volume=(box.maxX-box.minX)*(box.maxY-box.minY)*(box.maxZ-box.minZ);if(cell.side()==1&&volume>best){best=volume;point=new Vec3(BASE.getX()+(box.minX+box.maxX)/2,BASE.getY()+(box.minY+box.maxY)/2,BASE.getZ()+(box.minZ+box.maxZ)/2);}}need(point!=null&&NativeFluidWorld.atPoint(level,point).is(Fluids.WATER),"actual native contact uses borrowed stationary volume");
        loadFluids(level,owner,fluids(3,1,777));var raw=owner.saveWithoutMetadata(level.registryAccess());var update=owner.getUpdateTag(level.registryAccess());need(!update.toString().contains("private:")&&!update.toString().contains("future:trapdoor-fluid"),"public update excludes opaque slot/envelope ownership");var client=new NativeTrapdoorEntity(types[0],BASE,owner.getBlockState());client.loadWithComponents(update,level.registryAccess());need(client.containedFluids().occupied(0)&&client.containedFluids().get(0).isEmpty()&&client.containedFluids().get(1).getAmount()==777,"public update retains known amount and opaque occupancy");
        var malformed=raw.copy();malformed.getCompound(NativeFluidSlots.KEY).putString("Side0","private:future-slot-format");owner.loadWithComponents(malformed,level.registryAccess());need(owner.containedFluids().occupied(0)&&!NativeFluidWorld.canFill(owner,0,new FluidStack(Fluids.WATER,1000)),"future slot representation remains occupied");NativeFluidWorld.set(owner,1,FluidStack.EMPTY);var retained=owner.saveWithoutMetadata(level.registryAccess()).getCompound(NativeFluidSlots.KEY);need(retained.getString("Side0").equals("private:future-slot-format")&&retained.getString("EnvelopeOwner").equals("private:trapdoor-envelope"),"editing other side retains original future type and envelope siblings");
        var legacy=choices();legacy.putBoolean("Waterlogged",true);owner.loadWithComponents(legacy,level.registryAccess());NativeFluidWorld.set(owner,1,new FluidStack(Fluids.LAVA,333));var migrated=owner.saveWithoutMetadata(level.registryAccess());client.loadWithComponents(migrated,level.registryAccess());need(client.containedFluids().get(0).getAmount()==1000&&client.containedFluids().get(1).getAmount()==333,"legacy alias survives opposite-side edit");NativeFluidWorld.set(owner,0,FluidStack.EMPTY);NativeFluidWorld.set(owner,1,FluidStack.EMPTY);client.loadWithComponents(owner.saveWithoutMetadata(level.registryAccess()),level.registryAccess());need(!client.containedFluids().any(),"drained legacy alias remains suppressed on reload");
        var failed=raw.copy();failed.getCompound(NativeFluidSlots.KEY).getCompound("Side1").putInt("Amount",1000);failed.putInt("NativeTrapdoorLinks",2);owner.loadWithComponents(failed,level.registryAccess());need(owner.inert()&&!NativeFluidWorld.set(owner,1,FluidStack.EMPTY),"inert original refuses owned slot mutation");actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BUCKET));var hit=new BlockHitResult(Vec3.atCenterOf(BASE),Direction.UP,BASE,false);need(!actor.gameMode.useItemOn(actor,level,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().is(Items.BUCKET)&&owner.containedFluids().get(1).getAmount()==1000,"actual inert bucket cannot transfer retained contents");level.setBlock(BASE.east(),Blocks.SPONGE.defaultBlockState(),3);NativeFluidSponge.changed(level,BASE);need(owner.saveWithoutMetadata(level.registryAccess()).getCompound(NativeFluidSlots.KEY).equals(failed.getCompound(NativeFluidSlots.KEY)),"inert sponge preserves exact original envelope");level.setBlock(BASE.east(),Blocks.AIR.defaultBlockState(),18);owner.loadWithComponents(raw,level.registryAccess());NativeFluidWorld.changed(owner);level.setBlock(BASE.east(),Blocks.SPONGE.defaultBlockState(),3);NativeFluidSponge.changed(level,BASE);need(owner.containedFluids().get(1).isEmpty()&&owner.containedFluids().raw(0).getString("Owner").equals("private:trapdoor-slot"),"sponge drains known water and preserves opaque other side");level.setBlock(BASE.east(),Blocks.AIR.defaultBlockState(),18);
        NativeFluidWorld.set(owner,1,new FluidStack(Fluids.LAVA,1000));NativeFluidWorld.changed(owner);need(level.getBlockState(BASE).getLightEmission(level,BASE)==15,"source block light includes owned lava emission");NativeFluidWorld.set(owner,1,FluidStack.EMPTY);NativeFluidWorld.changed(owner);need(level.getBlockState(BASE).getLightEmission(level,BASE)==0,"source artwork does not invent world-light emission");
        var capture=put(level,BASE.east(3),0,choices());var cp=capture.getBlockPos();level.setBlock(cp.east(),Blocks.WATER.defaultBlockState(),18);capture.capturePlacementFluids(Blocks.AIR.defaultBlockState());need(!capture.containedFluids().any(),"transverse adjacent water never becomes owned placement data");level.setBlock(cp.east(),Blocks.AIR.defaultBlockState(),18);level.setBlock(cp.above(),Blocks.WATER.defaultBlockState(),18);capture.capturePlacementFluids(Blocks.LAVA.defaultBlockState());need(capture.containedFluids().get(1).is(Fluids.WATER)&&!capture.containedFluids().occupied(0),"normal-side adjacent fluid takes precedence over displaced fallback");level.setBlock(cp.above(),Blocks.AIR.defaultBlockState(),18);NativeFluidWorld.set(capture,1,FluidStack.EMPTY);capture.capturePlacementFluids(Blocks.WATER.defaultBlockState());need(capture.containedFluids().get(0).getAmount()==1000&&capture.containedFluids().get(1).getAmount()==1000,"displaced physical water fills both eligible opening sides");
        var diagonal=put(level,DIAGONAL,1,choices());loadFluids(level,diagonal,fluids(1,0,1000));need(!diagonal.fluidVolumeSnapshot().cells().isEmpty(),"diagonal host prepares exact fluid void when wet");var cached=diagonal.fluidVolumeSnapshot();long revision=diagonal.fluidGeometryRevision();var choice=diagonal.settings();var data=choice.choices();var cosmetic=new NativeTrapdoorSettings(new com.vandorlabs.persistence.TrapdoorData(data.texture,data.position,2,data.trigger,false,data.cover,data.sliding,data.intoWall,data.overSurface),choice.channels(),choice.facing(),choice.hingeSide(),choice.rotationFlipped(),true);actor.setPos(DIAGONAL.getX()+.5,DIAGONAL.getY()+1,DIAGONAL.getZ()+.5);need(diagonal.configure(actor,cosmetic,diagonal.inverted(),null)&&diagonal.fluidVolumeSnapshot()==cached&&diagonal.fluidGeometryRevision()==revision,"cosmetic layout preserves prepared physical volume identity");
        loadFluids(level,owner,fluids(1,3,777));owner.requestOpen(true);NativeFluidWorld.changed(owner);level.setChunkForced(BASE.getX()>>4,BASE.getZ()>>4,true);System.out.println("[vandorlabs][trapdoor-fluid] behavior PASS packetbuckets/borrowedcontact/nooutlets/opaque/futureformat/legacyalias/inert/sponge/light/cosmeticreuse");
    }
    private static void read(ServerLevel level){level.getChunkAt(BASE);var owner=tile(level,BASE);owner.onLoad();NativeFluidWorld.changed(owner);need(owner.containedFluids().get(0).getAmount()==777&&owner.containedFluids().get(0).get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag().getInt("FixtureKind")==1&&owner.containedFluids().raw(1).getString("Owner").equals("private:trapdoor-slot"),"complete process restores tagged and opaque stationary ownership");need(owner.open()&&owner.effectiveFluidSnapshot().side(1).fluid().getAmount()==777&&!owner.containedFluids().get(1).is(Fluids.WATER),"separate process re-derives borrowed water without saving it");var envelope=owner.saveWithoutMetadata(level.registryAccess()).getCompound(NativeFluidSlots.KEY);need(envelope.getString("EnvelopeOwner").equals("private:trapdoor-envelope"),"private envelope siblings survive restart");owner.requestOpen(false);NativeFluidWorld.changed(owner);need(owner.effectiveFluidSnapshot().side(1).fluid().isEmpty()&&owner.containedFluids().get(0).getAmount()==777,"closure withdraws overlay without moving owned fluid");}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;var level=event.getServer().overworld();if(phase().endsWith("write"))write(level);else read(level);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][trapdoor-fluid] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
